  const ref=useRef<HTMLDialogElement>(null);const callback=useRef(onClose);callback.current=onClose;
  useEffect(()=>{const el=ref.current;const prev=document.activeElement as HTMLElement;el?.showModal();const close=(e:Event)=>{e.preventDefault();callback.current();};el?.addEventListener('cancel',close);return()=>{el?.removeEventListener('cancel',close);el?.close();prev?.focus();};},[]);
