function ScoreChart({history,player}:{history:Histories;player?:Player}){
  const entries=Object.values(history).filter(h=>(!player||h.player===player)&&Number.isFinite(h.timestamp)&&Number(h.timestamp)>0&&Number.isFinite(Number(h.tier))).sort((a,b)=>a.timestamp!-b.timestamp!);
  if(!entries.length)return <Empty title="Sin actividad fechada" text="Los registros antiguos sin fecha cuentan para el ranking, pero no se ubican en el tiempo."/>;
  const series=(player?[player]:PLAYERS).map(p=>{let total=0;return {p,values:entries.filter(h=>h.player===p).map(h=>({x:h.timestamp!,y:(total+=points(h.tier))}))};});
  const min=entries[0].timestamp!,max=Math.max(min+86400000,entries[entries.length-1].timestamp!);const yMax=Math.max(1,...series.flatMap(s=>s.values.map(v=>v.y)));
  return <div className="score-chart"><svg viewBox="0 0 700 240" role="img" aria-label="Puntos acumulados de las completaciones con fecha registrada"><title>Puntos de registros fechados</title>{[0,.25,.5,.75,1].map(v=><g key={v}><line x1="55" y1={200-v*180} x2="685" y2={200-v*180} stroke="#ffffff18"/><text x="45" y={204-v*180} fill="#bcd9f0" textAnchor="end" fontSize="11">{fmt(yMax*v)}</text></g>)}{series.map(s=><polyline key={s.p} fill="none" stroke={PLAYER_META[s.p].color} strokeWidth="3" strokeLinejoin="round" points={[[55,200],...s.values.map(v=>[55+(v.x-min)/(max-min)*625,200-v.y/yMax*180])].map(p=>p.join(',')).join(' ')}/>)}<text x="55" y="229" fill="#bcd9f0" fontSize="11">{shortDate(min)}</text><text x="680" y="229" fill="#bcd9f0" textAnchor="end" fontSize="11">{shortDate(entries[entries.length-1].timestamp!)}</text></svg><div className="chart-legend">{series.map(s=><span key={s.p}><i style={{background:PLAYER_META[s.p].color}}/>{s.p}</span>)}</div><p className="caption">Solo registros con fecha. El historial antiguo está incompleto; esta curva no representa el puntaje total histórico.</p></div>;
}
